// n8n Code Node
// Name: CONFIG - Amazon Image Listing Factory - 5 Stage Stable V2
// _MY_PRODUCT contains: main_image.jpg + product_info.json
// Listing 1 contains: main_image.jpg + image 2.jpg ... image 7.jpg

const MY_PRODUCT_FOLDER_ID = "YOUR_PRODUCT_FOLDER_ID";
const COMPETITOR_LISTING_FOLDER_ID = "YOUR_COMPETITOR_FOLDER_ID";

const config = {
  workflow_version: "AMAZON_IMAGE_LISTING_FACTORY_CURRENT_MINIMAL_PROMPTS_FORMDATA_HTTP_FIXED",
  mode: "one_product_folder_one_competitor_listing_folder",

  credentials_note: {
    google_drive_credential_name: "Select your own Google Drive credential",
    openai_auth: "HTTP nodes use the saved OpenAI credential; no key is embedded."
  },

  openai: {
    generation_model: "gpt-image-2",
    analysis_model: "gpt-5.5",
    generation_endpoint: "https://api.openai.com/v1/images/edits",
    analysis_endpoint: "https://api.openai.com/v1/responses",
    image_size: "1024x1024",
    image_quality: "medium",
    analysis_reasoning_effort: "medium",
    analysis_text_verbosity: "medium"
  },

  folders: {
    my_product_folder_id: MY_PRODUCT_FOLDER_ID,
    competitor_listing_folder_id: COMPETITOR_LISTING_FOLDER_ID
  },

  file_names: {
    product_reference_image: "main_image.jpg",
    product_info_json: "product_info.json",
    competitor_main_image: "main_image.jpg",
    competitor_secondary_pattern: "image #.jpg"
  },

  // 6-image listing plan.
  // Slot 1 uses competitor main_image.jpg.
  // Slots 2-6 use image 2.jpg through image 6.jpg.
  generation_plan: [
    { slot: 1, slot_key: "main_image", competitor_filename: "main_image.jpg", output_filename: "generated_image_1.png" },
    { slot: 2, slot_key: "image 2", competitor_filename: "image 2.jpg", output_filename: "generated_image_2.png" },
    { slot: 3, slot_key: "image 3", competitor_filename: "image 3.jpg", output_filename: "generated_image_3.png" },
    { slot: 4, slot_key: "image 4", competitor_filename: "image 4.jpg", output_filename: "generated_image_4.png" },
    { slot: 5, slot_key: "image 5", competitor_filename: "image 5.jpg", output_filename: "generated_image_5.png" },
    { slot: 6, slot_key: "image 6", competitor_filename: "image 6.jpg", output_filename: "generated_image_6.png" },
    { slot: 7, slot_key: "image 7", competitor_filename: "image 7.jpg", output_filename: "generated_image_7.png" }
  ],

  output_mode: {
    analysis_outputs_are_variables: true,
    no_manual_md_download_between_stages: true,
    stage_1_variable: "stage1_competitor_strategy_analysis",
    stage_2_variable: "stage2_safe_generation_brief",
    stage_4_variable: "stage4_design_difference_thinking"
  }
};

// Start with one reference. Remove this line after the first successful test.
config.generation_plan = config.generation_plan.slice(0, 1);
return [{ json: config }];

const items = $input.all();
const files = items.map(i => i.json);

function norm(s) {
  return String(s || "").trim().toLowerCase();
}

function isImage(f) {
  return /\.(jpg|jpeg|png|webp)$/i.test(String(f.name || ""));
}

const productInfo = files.find(f => norm(f.name) === "product_info.json");

const mainImage =
  files.find(f => norm(f.name) === "main_image.jpg") ||
  files.find(f => isImage(f));

const refPhotos = files
  .filter(isImage)
  .map(f => ({
    id: f.id,
    name: f.name,
    mimeType: f.mimeType || ""
  }));

if (!productInfo) {
  throw new Error(
    "product_info.json not found in _MY_PRODUCT folder. Found: " +
    files.map(f => f.name).join(", ")
  );
}

if (!mainImage) {
  throw new Error(
    "main_image.jpg/product image not found in _MY_PRODUCT folder. Found: " +
    files.map(f => f.name).join(", ")
  );
}

const cfg = $("Settings").item.json;

return [
  {
    json: {
      ...cfg,
      productInfoFileId: productInfo.id,
      productInfoFileName: productInfo.name,
      productImageFileId: mainImage.id,
      productImageFileName: mainImage.name,
      refPhotoIds: refPhotos,
      productFolderFiles: files.map(f => ({
        id: f.id,
        name: f.name,
        mimeType: f.mimeType || ""
      }))
    }
  }
];

const item = $input.item;

if (!item.binary || !item.binary.data) {
  throw new Error("product_info.json binary was not downloaded as binary.data");
}

const buffer = await this.helpers.getBinaryDataBuffer(0, "data");

let rawText = buffer.toString("utf8");

// Remove UTF-8 BOM if present
rawText = rawText.replace(/^\uFEFF/, "").trim();

let productInfo;

try {
  productInfo = JSON.parse(rawText);
} catch (e) {
  throw new Error(
    "product_info.json could not be parsed as JSON: " +
    e.message +
    "\nPreview: " +
    rawText.slice(0, 500)
  );
}

const base = $("Sort Product Files").item.json;

return [
  {
    json: {
      ...base,
      productInfo,
      product_info_raw: productInfo,
      product_info_text_preview: rawText.slice(0, 1000),
      product_info_ready: true
    },
    binary: {}
  }
];

const base = $("Parse product_info.json").item.json;

if (!$input.item.binary || !$input.item.binary.data) {
  throw new Error("Product image binary was not downloaded as binary.data");
}

const productBinary = $input.item.binary.data;

return [
  {
    json: {
      ...base,
      product_image_ready: true,
      product_image_binary_field: "product_image",
      product_image_mime_type: productBinary.mimeType || "",
      product_image_file_name: productBinary.fileName || base.productImageFileName || "main_image.jpg"
    },
    binary: {
      product_image: productBinary
    }
  }
];

const base = $json;

if (!base.folders || !base.folders.competitor_listing_folder_id) {
  throw new Error("competitor_listing_folder_id is missing from config.folders");
}

return [
  {
    json: {
      ...base,
      id: base.folders.competitor_listing_folder_id,
      folder_role: "Listing 1",
      name: "Listing 1"
    },
    binary: $input.item.binary || {}
  }
];

const files = $input.all().map(i => i.json);

const productItem = $("Rename Product Binary").item;
const cfg = productItem.json;

if (!productItem.binary || !productItem.binary.product_image) {
  throw new Error("product_image binary is missing from Rename Product Binary node");
}

if (!Array.isArray(cfg.generation_plan) || cfg.generation_plan.length === 0) {
  throw new Error("generation_plan is missing or empty in config");
}

function norm(s) {
  return String(s || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function isImageFile(f) {
  const name = String(f.name || "");
  const mime = String(f.mimeType || "");
  return /\.(jpg|jpeg|png|webp)$/i.test(name) || mime.startsWith("image/");
}

function findFile(filename) {
  const target = norm(filename);

  return files.find(f => norm(f.name) === target);
}

const imageFiles = files.filter(isImageFile);

const slots = [];

for (const plan of cfg.generation_plan) {
  const f = findFile(plan.competitor_filename);

  if (!f) {
    throw new Error(
      `Missing competitor file "${plan.competitor_filename}" in Listing 1.\n` +
      `Found files: ${files.map(x => x.name).join(", ")}`
    );
  }

  if (!isImageFile(f)) {
    throw new Error(
      `Competitor file "${f.name}" was found, but it does not look like an image file. mimeType: ${f.mimeType || "unknown"}`
    );
  }

  slots.push({
    json: {
      ...cfg,
      ...plan,
      competitorFileId: f.id,
      competitorFileName: f.name,
      competitorMimeType: f.mimeType || "",
      retry_count: 0,
      attempt_index: 0,
      passed: false,
      availableCompetitorImages: imageFiles.map(x => ({
        id: x.id,
        name: x.name,
        mimeType: x.mimeType || ""
      }))
    },
    binary: {
      product_image: productItem.binary.product_image
    }
  });
}

return slots;

const inputItems = $input.all();

const outputItems = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];

  if (!item.binary || !item.binary.product_image) {
    throw new Error(
      `product_image binary is missing from item ${i + 1}`
    );
  }

  if (!item.binary || !item.binary.data) {
    throw new Error(
      `Competitor image binary was not downloaded as binary.data for item ${i + 1}`
    );
  }

  const productBinary = item.binary.product_image;
  const competitorBinary = item.binary.data;

  outputItems.push({
    json: {
      ...item.json,

      competitor_image_ready: true,

      competitor_image_binary_field: "competitor_image",

      competitor_image_mime_type:
        competitorBinary.mimeType || "",

      competitor_image_file_name:
        competitorBinary.fileName ||
        item.json.competitorFileName ||
        "competitor_image.jpg"
    },

    binary: {
      product_image: productBinary,
      competitor_image: competitorBinary
    }
  });
}

return outputItems;

function extractResponsesText(response, stageName) {
  if (!response) return "";
  if (typeof response.output_text === "string" && response.output_text.trim()) return response.output_text.trim();
  if (Array.isArray(response.output)) {
    const parts = [];
    for (const outputItem of response.output) {
      if (!outputItem || !Array.isArray(outputItem.content)) continue;
      for (const contentItem of outputItem.content) {
        if (!contentItem) continue;
        if (contentItem.type === "output_text" && typeof contentItem.text === "string") parts.push(contentItem.text);
        if (contentItem.type === "text" && typeof contentItem.text === "string") parts.push(contentItem.text);
      }
    }
    if (parts.length) return parts.join("\n").trim();
  }
  function fallbackFindText(x) {
    if (x == null) return "";
    if (typeof x === "string") return x;
    if (Array.isArray(x)) return x.map(fallbackFindText).filter(Boolean).join("\n");
    if (typeof x === "object") {
      if (x.output_text) return fallbackFindText(x.output_text);
      if (x.text) return fallbackFindText(x.text);
      if (x.content) return fallbackFindText(x.content);
      if (x.output) return fallbackFindText(x.output);
      if (x.message) return fallbackFindText(x.message);
      return Object.values(x).map(fallbackFindText).filter(Boolean).join("\n");
    }
    return String(x);
  }
  const fallbackText = fallbackFindText(response).trim();
  if (fallbackText) return fallbackText;
  throw new Error(`Could not extract ${stageName} text from OpenAI response. Preview: ` + JSON.stringify(response).slice(0, 2000));
}

const responses = $input.all();
const requestItems = $("Build Stage 1 - Competitor Strategy Analysis Request").all();

return responses.map((responseItem, i) => {
  const originalItem = requestItems[i];
  if (!originalItem) throw new Error(`Matching Stage 1 request item not found for item ${i}`);
  const text = extractResponsesText(responseItem.json, "Stage 1 Competitor Strategy Analysis");
  return {
    json: {
      ...originalItem.json,
      stage1_competitor_strategy_analysis: text,
      stage1_output_markdown: text,
      stage1_raw_preview: JSON.stringify(responseItem.json).slice(0, 3000)
    },
    binary: originalItem.binary
  };
});

const inputItems = $input.all();

const STAGE_2_PROMPT = `
Using the real product photo, Product Info document, and competitor strategy analysis,
create a SAFE generation brief.

Focus only on:
- preserving real product accuracy
- preventing hallucinated physical details
- preventing unsupported claims/features
- preserving visible screen/icons if present
- keeping only the supported information directly relevant to the competitor image's PRIMARY communication goal

The competitor image defines the communication topic and structure.
Product Info defines the correct factual content.
Stage 1 defines the supported adaptation direction.

Do not infer hidden functionality from the competitor image.
Do NOT give layout, composition, or art direction instructions.

If a physical detail is unclear, represent it generically instead of inventing details.
Do not expose physical feature locations not clearly visible in the real product photo.

Only include supported product capabilities that are DIRECTLY important to the competitor image's main buyer takeaway.
A feature being supported does NOT mean it should appear in the image.

If the competitor image communicates through multiple buyer scenarios, multi-panel storytelling,
or lifestyle versatility â€” preserve that communication logic in the SAFE brief.

If the competitor image does NOT use communication text as a dominant visual element,
the SAFE brief must NOT include taglines, feature labels, specifications, or callouts.
In this case, explicitly instruct the generated image to remain text-free.

Unsupported specific use cases should be SAFELY REPLACED, not removed completely,
when they are central to the competitor image's communication structure.

Replace unsupported claims with broader supported contexts that preserve the same intent.

The SAFE brief should preserve the competitor image's communication richness when
that richness is central to the image strategy.

Accessories, packaging, cables, included-item displays should be excluded unless
ESSENTIAL to the competitor image's primary communication goal.

Keep the response short, practical, and specific.
Return markdown text only.
`.trim();

const outputItems = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];

  if (!item.binary?.product_image) throw new Error(`product_image binary missing on item ${i}`);
  if (!item.binary?.competitor_image) throw new Error(`competitor_image binary missing on item ${i}`);

  const productBuf = await this.helpers.getBinaryDataBuffer(i, "product_image");
  const competitorBuf = await this.helpers.getBinaryDataBuffer(i, "competitor_image");

  const productMime = item.binary.product_image.mimeType || "image/jpeg";
  const competitorMime = item.binary.competitor_image.mimeType || "image/jpeg";
  const productDataUrl = `data:${productMime};base64,${productBuf.toString("base64")}`;
  const competitorDataUrl = `data:${competitorMime};base64,${competitorBuf.toString("base64")}`;

  const productInfoText = JSON.stringify(item.json.productInfo || {}, null, 2);
  const stage1Text = item.json.stage1_competitor_strategy_analysis || item.json.stage1_output_markdown || "";

  const fullPrompt = `${STAGE_2_PROMPT}\n\n==============================\nPRODUCT INFO DOCUMENT\n==============================\n\n${productInfoText}\n\n==============================\nCOMPETITOR STRATEGY ANALYSIS FROM STAGE 1\n==============================\n\n${stage1Text}\n\n==============================\nFINAL SAFE BRIEF CHECK\n==============================`;

  const body = {
    model: item.json.openai?.analysis_model || "gpt-5.5",
    reasoning: { effort: item.json.openai?.analysis_reasoning_effort || "medium" },
    text: { verbosity: item.json.openai?.analysis_text_verbosity || "medium" },
    input: [{
      role: "user",
      content: [
        { type: "input_text", text: fullPrompt },
        { type: "input_image", image_url: productDataUrl },
        { type: "input_image", image_url: competitorDataUrl }
      ]
    }]
  };

  outputItems.push({
    json: { ...item.json, active_prompt: fullPrompt, stage2_prompt: STAGE_2_PROMPT, stage2_full_prompt: fullPrompt, stage2_request_body: body },
    binary: item.binary
  });
}

return outputItems;

function extractResponsesText(response, stageName) {
  if (!response) return "";
  if (typeof response.output_text === "string" && response.output_text.trim()) return response.output_text.trim();
  if (Array.isArray(response.output)) {
    const parts = [];
    for (const outputItem of response.output) {
      if (!outputItem || !Array.isArray(outputItem.content)) continue;
      for (const contentItem of outputItem.content) {
        if (!contentItem) continue;
        if (contentItem.type === "output_text" && typeof contentItem.text === "string") parts.push(contentItem.text);
        if (contentItem.type === "text" && typeof contentItem.text === "string") parts.push(contentItem.text);
      }
    }
    if (parts.length) return parts.join("\n").trim();
  }
  throw new Error(`Could not extract ${stageName} text. Preview: ` + JSON.stringify(response).slice(0, 1000));
}

const responses = $input.all();
const requestItems = $("Build Stage 2 - Safe Generation Brief Request").all();

return responses.map((responseItem, i) => {
  const originalItem = requestItems[i];
  if (!originalItem) throw new Error(`Matching Stage 2 request item not found for item ${i}`);
  const text = extractResponsesText(responseItem.json, "Stage 2 Safe Generation Brief");
  return {
    json: {
      ...originalItem.json,
      stage2_safe_generation_brief: text,
      stage2_output_markdown: text,
      stage2_raw_preview: JSON.stringify(responseItem.json).slice(0, 3000)
    },
    binary: originalItem.binary
  };
});

const inputItems = $input.all();

const STAGE_3_PROMPT = `
Use:
- the FIRST attached image as the competitor/reference image for communication strategy,
  customer takeaway, information hierarchy, and visual storytelling approach
- the SECOND attached image as the real product photo and ONLY source of truth for the product
- the SAFE Generation Brief as the factual execution guide

Create a premium Amazon listing image.

Preserve:
- product accuracy
- proportions
- materials
- screen/icons if present
- supported claims only

Understand the competitor image's communication goal,
but create an original visual execution.
Focus on communicating the same buyer takeaway, not recreating the same scene.

Do NOT closely mimic the competitor image's exact layout, composition, object placement,
or spatial structure.

Preserve the competitor image's communication architecture.
If the competitor image communicates through multiple use-case scenes, multi-panel storytelling,
lifestyle versatility, or layered educational structure â€” preserve that level of richness.

Do not collapse a multi-scenario competitor image into a single product beauty shot
or a generic portability poster.

Every major visual element should support the competitor image's PRIMARY communication goal.
Avoid adding unrelated supported features not important to the main buyer takeaway.

When the SAFE Generation Brief replaces unsupported claims with supported alternatives,
visually communicate the supported version instead.

Prioritize communication clarity over decorative visuals.

Preserve the competitor image's presentation category:
- If the competitor image is colorful, scenic, lifestyle-focused, visually rich â€”
  the generated image should preserve that atmosphere.
- If the competitor image uses plain white/near-white background with isolated product â€”
  the generated image must also use a plain white/near-white background.
  Do not introduce environmental scenery, lifestyle backgrounds, or atmospheric gradients.

STRICT TEXT RULE:
If the competitor image does NOT use communication text as a major part of the visual structure,
the generated image must remain text-free.
Small branding or packaging text does NOT count as permission to add feature labels or callouts.

Avoid:
- unsupported claims
- hallucinated physical details
- fake ports or mechanisms
- unsupported features
- unrelated secondary objects

Aspect ratio: 1:1
`.trim();

function extractStage2Text(value) {
  if (!value) return "";
  if (typeof value === "string") return value;
  if (typeof value === "object") {
    if (typeof value.text === "string") return value.text;
    if (typeof value.output_text === "string") return value.output_text;
    return JSON.stringify(value, null, 2);
  }
  return String(value);
}

return inputItems.map((item, i) => {
  if (!item.binary?.product_image) throw new Error(`product_image binary missing on item ${i}`);
  if (!item.binary?.competitor_image) throw new Error(`competitor_image binary missing on item ${i}`);

  const stage2Text = extractStage2Text(item.json.stage2_safe_generation_brief) || extractStage2Text(item.json.stage2_output_markdown) || "";

  const fullPrompt = `${STAGE_3_PROMPT}\n\n==============================\nSAFE GENERATION BRIEF FROM STAGE 2\n==============================\n\n${stage2Text}\n\n==============================\nFINAL GENERATION CHECK\n==============================`;

  return {
    json: { ...item.json, active_prompt: fullPrompt, stage3_prompt: STAGE_3_PROMPT, stage3_generation_prompt: fullPrompt },
    binary: { ...item.binary, image_1_competitor: item.binary.competitor_image, image_2_product: item.binary.product_image }
  };
});

function findB64(obj) {
  if (!obj) return null;
  if (typeof obj === "string") return null;
  if (obj.b64_json) return obj.b64_json;
  if (Array.isArray(obj)) { for (const item of obj) { const found = findB64(item); if (found) return found; } }
  if (typeof obj === "object") { for (const value of Object.values(obj)) { const found = findB64(value); if (found) return found; } }
  return null;
}

const responses = $input.all();
const requestItems = $("Build Stage 3 - First Image Generation Prompt").all();
const outputItems = [];

for (let i = 0; i < responses.length; i++) {
  const responseItem = responses[i];
  const originalItem = requestItems[i];
  if (!originalItem) throw new Error(`Matching Stage 3 request item not found for item ${i}`);

  const b64 = findB64(responseItem.json);
  if (!b64) throw new Error(`No b64_json found in Stage 3 response for item ${i}. Preview: ` + JSON.stringify(responseItem.json).slice(0, 1500));

  const cleanB64 = String(b64).replace(/^data:image\/\w+;base64,/, "");
  const buffer = Buffer.from(cleanB64, "base64");
  const filename = `slot_${originalItem.json.slot || "unknown"}_stage3_first_image.png`;
  const outputBinary = await this.helpers.prepareBinaryData(buffer, filename, "image/png");

  outputItems.push({
    json: { ...originalItem.json, stage3_first_image_created: true, stage3_first_image_filename: filename },
    binary: { ...originalItem.binary, previous_output: outputBinary, stage3_first_image: outputBinary }
  });
}

return outputItems;

const inputItems = $input.all();

const STAGE_4_PROMPT = `
Look at the previous generated image.

Preserve:
- the communication goal
- the customer takeaway
- the important factual information
- the information density
- the storytelling depth

Do not preserve:
- the layout
- the composition
- the framing
- the visual flow
- the spatial structure

The redesign should feel like a different premium advertising designer created the image
from scratch while preserving the same buyer-facing message.

Preserve the MESSAGE, not the geometry.

If the image uses multiple scenarios, layered storytelling, educational structure,
or lifestyle contexts â€” preserve a comparable level of communication richness.

Do not simplify a rich image into a minimal advertisement unless the original is minimal.
Avoid small cosmetic changes.
The redesign should introduce a noticeably different visual execution at first glance.

Keep the redesign: premium, visually original, communication-first, commercially realistic.
Return markdown text only.
`.trim();

function extractText(value) {
  if (!value) return "";
  if (typeof value === "string") return value;
  if (typeof value === "object") {
    if (typeof value.text === "string") return value.text;
    if (typeof value.output_text === "string") return value.output_text;
    return JSON.stringify(value, null, 2);
  }
  return String(value);
}

const outputItems = [];

for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  if (!item.binary?.previous_output) throw new Error(`previous_output binary missing on item ${i}`);

  const previousBuf = await this.helpers.getBinaryDataBuffer(i, "previous_output");
  const previousMime = item.binary.previous_output.mimeType || "image/png";
  const previousDataUrl = `data:${previousMime};base64,${previousBuf.toString("base64")}`;

  const stage2Text = extractText(item.json.stage2_safe_generation_brief) || extractText(item.json.stage2_output_markdown) || "";

  const fullPrompt = `${STAGE_4_PROMPT}\n\n==============================\nSAFE GENERATION BRIEF FROM STAGE 2\n==============================\n\n${stage2Text}\n\n==============================\nFINAL STAGE 4 CHECK\n==============================`;

  const body = {
    model: item.json.openai?.analysis_model || "gpt-5.5",
    reasoning: { effort: item.json.openai?.analysis_reasoning_effort || "medium" },
    text: { verbosity: item.json.openai?.analysis_text_verbosity || "medium" },
    input: [{ role: "user", content: [{ type: "input_text", text: fullPrompt }, { type: "input_image", image_url: previousDataUrl }] }]
  };

  outputItems.push({
    json: { ...item.json, active_prompt: fullPrompt, stage4_prompt: STAGE_4_PROMPT, stage4_full_prompt: fullPrompt, stage4_request_body: body },
    binary: item.binary
  });
}

return outputItems;

