        if (contentItem.type === "output_text" && typeof contentItem.text === "string") parts.push(contentItem.text);
        if (contentItem.type === "text" && typeof contentItem.text === "string") parts.push(contentItem.text);
      }
    }
    if (parts.length) return parts.join("\n").trim();
  }
  throw new Error(`Could not extract ${stageName} text. Preview: ` + JSON.stringify(response).slice(0, 1000));
}

const responses = $input.all();
const requestItems = $("Build Stage 4 - Design Difference Thinking Request").all();

return responses.map((responseItem, i) => {
  const originalItem = requestItems[i];
  if (!originalItem) throw new Error(`Matching Stage 4 request item not found for item ${i}`);
  const text = extractResponsesText(responseItem.json, "Stage 4 Design Difference Thinking");
  return {
    json: { ...originalItem.json, stage4_design_difference_thinking: text, stage4_output_markdown: text },
    binary: originalItem.binary
  };
});

const inputItems = $input.all();

const STAGE_5_PROMPT = `
